import React, { useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import singer from '../../assets/images/artists_images/singer.png'

// Register GSAP ScrollTrigger plugin
gsap.registerPlugin(ScrollTrigger);

function Artists() {
  useEffect(() => {
    const ctx = gsap.context(() => {
      const cardsElement = document.querySelector(".cards");
      const cardWidth = cardsElement.firstElementChild.offsetWidth;

      gsap.to(".cards", {
        x: () =>
          `-${cardsElement.scrollWidth - window.innerWidth + cardWidth}px`,
        scrollTrigger: {
          trigger: ".artists",
          scroller: "body",
          start: "top top",
          end: () =>
            `+=${cardsElement.scrollWidth - window.innerWidth + cardWidth}`,
          scrub: true,
          pin: true,
        },
      });
    });

    return () => ctx.revert(); // Cleanup GSAP on component unmount
  }, []);

  // Data for cards
  const cardsData = [
    {
      image: "data:image/jpeg;base64,",
      title: " Rock Bands ",
    },
    {
      image: "data:image/jpeg;base64,",
      title: "Stand-up Comedy ",
    },
    {
      image: "data:image/jpeg;base64,",
      title: "Open Mic Events",
    },
    {
      image: "data:image/jpeg;base64,",
      title: "Live Music",
    },
    {
      image: "data:image/jpeg;base64,",
      title: "DJ Nights",
    },
  ];

  return (
    <div className="artists h-screen w-full  flex items-center overflow-hidden bg-black">
      {/* Container for Title and Cards */}
      <div className="flex items-center w-full p-10">
        {/* Title Container */}
        <div className="title-container flex flex-col items-center md:items-start md:mr-10">
          <h1 className="text-transparent bg-clip-text bg-gradient-to-r from-sand-start to-sand-end text-4xl font-bold md:text-5xl  mb-10 text-center md:text-left">
            Meet Our Talented Artists
          </h1>
        </div>

        {/* Cards Container */}
        <div className="cards flex w-max space-x-10 p-10">
          {cardsData.map((card, index) => (
            <div
              key={index}
              className="card flex-shrink-0 flex flex-col items-center h-[80vh] w-[90vw] md:w-[40vw] bg-gray-900  rounded-lg overflow-hidden shadow-lg"
            >
              {/* Image */}
              <img
                className="h-4/5 w-full object-cover"
                src={card.image}
                alt={card.title}
              />
              {/* Title */}
              <h1 className="text-transparent bg-clip-text bg-gradient-to-r from-bronze-start to-bronze-end  font text-2xl font-bold mt-2">
                {card.title}
              </h1>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Artists;
